export type SpeciesReviewStatus = 'machine-verified' | 'review-required';

export interface SpeciesPatternRecord {
  mode: 'plain' | 'veined' | 'speckled' | 'picotee' | 'star';
  color: string;
  strength: number;
  veinFrequency: number;
  spotDensity: number;
  edgeStrength: number;
  centerStrength: number;
  seed: number;
}

export interface SpeciesDatabaseRecord {
  id: string;
  displayName: string;
  scientificName: string;
  family: string;
  taxonomy: null | {
    key: string | number | null;
    acceptedName: string | null;
    canonicalName: string | null;
    rank: string | null;
    status: string | null;
    matchType: string | null;
    confidence: number;
    classification: Array<{ key: string | number; name: string; rank: string }>;
  };
  pattern: SpeciesPatternRecord;
  references: Array<{
    label: string;
    url: string;
    doi?: string;
    usage: string;
    metadata: null | {
      doi: string;
      title: string | null;
      publisher: string | null;
      published: string | null;
      authors: string[];
      licenseUrls: string[];
      url: string;
    };
  }>;
  provenance: {
    eflowerLicense: string;
    taxonomyProvider: string;
    bibliographyProvider: string;
    sourceCount: number;
    confidence: number;
    taxonomicPrecision: 'species-or-below' | 'higher-rank-only' | 'unmatched';
    reviewStatus: SpeciesReviewStatus;
  };
}

export interface SpeciesDatabase {
  schemaVersion: 1;
  generatedAt: string | null;
  generationMode: 'network-refresh' | 'cached-build';
  stats: {
    speciesRecords: number;
    taxonomyMatched: number;
    machineVerified: number;
    sourceLinks: number;
    refreshFailures: number;
  };
  records: SpeciesDatabaseRecord[];
}

export const isSpeciesDatabase = (value: unknown): value is SpeciesDatabase => {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Partial<SpeciesDatabase>;
  if (candidate.schemaVersion !== 1 || !Array.isArray(candidate.records) || !candidate.stats) return false;
  const ids = new Set<string>();
  return candidate.records.every((record) => {
    if (!record || typeof record.id !== 'string' || typeof record.scientificName !== 'string') return false;
    if (ids.has(record.id) || !record.references?.every((source) => source.url.startsWith('https://'))) return false;
    ids.add(record.id);
    return Number.isFinite(record.provenance?.confidence)
      && ['machine-verified', 'review-required'].includes(record.provenance.reviewStatus);
  });
};

export const findSpeciesDatabaseRecord = (
  database: SpeciesDatabase | null,
  presetId: string,
): SpeciesDatabaseRecord | null => database?.records.find((record) => record.id === presetId) ?? null;

export const loadSpeciesDatabase = async (
  url = './data/species-database.json',
  fetcher: typeof fetch = fetch,
): Promise<SpeciesDatabase> => {
  const response = await fetcher(url);
  if (!response.ok) throw new Error(`Species DB request failed: ${response.status}`);
  const value: unknown = await response.json();
  if (!isSpeciesDatabase(value)) throw new Error('Species DB schema validation failed.');
  return value;
};
